"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["66951"],{32766(e){e.exports=JSON.parse('{"id":"FIN-359","slug":"reserve-ratio","term":"Reserve Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The reserve ratio is the proportion of a bank\'s deposits that it holds as reserves, either as cash in its vaults or as deposits at the central bank, rather than lending out.","explanation":["Banks do not keep all deposits as cash. They lend most of the money and hold only a fraction as reserves to meet day-to-day withdrawals. The reserve ratio measures that fraction.","For example, if a bank has 100 million of deposits and holds 10 million in reserves, its reserve ratio is 10%.","Some central banks set a minimum required reserve ratio as a policy tool. Raising it forces banks to hold more reserves and lend less, which can slow the economy. Lowering it frees up money for lending. In recent years, several major central banks have reduced or removed reserve requirements, relying instead on interest rates and liquidity rules to guide banking activity. Others still use reserve requirements actively.","The reserve ratio is linked to the idea of money creation in a fractional reserve banking system. When banks lend out deposits, the loans are spent and deposited elsewhere, allowing further lending. In practice, the amount of lending is also limited by capital requirements, demand for loans and central bank policy."],"note":"","total":1500,"prev":{"slug":"reserve-currency","term":"Reserve Currency"},"next":{"slug":"reserve-requirement","term":"Reserve Requirement"}}')}}]);